function divisorSubstrings(num, k) {
  const digits = String(num);
  const place = 10 ** (k - 1);
  let windowValue = 0;
  let count = 0;
  for (let i = 0; i < digits.length; i++) {
    if (i >= k) {
      windowValue -= Number(digits[i - k]) * place;
    }
    windowValue = windowValue * 10 + Number(digits[i]);
    if (i >= k - 1 && windowValue !== 0 && num % windowValue === 0) {
      count++;
    }
  }
  return count;
}

