function divisorSubstrings(num, k) {
  const text = num.toString();
  let total = 0;
  for (let start = 0; start + k <= text.length; start++) {
    const piece = parseInt(text.slice(start, start + k), 10);
    if (piece > 0 && Number.isInteger(num / piece)) total++;
  }
  return total;
}

