function generate(rand, size) {
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const length = size === 'large' ? pick(8, 10) : pick(1, 7);
  const style = rand();
  let num;
  if (length === 10) {
    num = 1000000000;
  } else if (style < 0.3) {
    // A repeated block such as 120120120 is divisible by many of its own pieces.
    const block = String(pick(1, 99));
    let text = '';
    while (text.length < length) text += block;
    num = Number(text.slice(0, length));
  } else if (style < 0.55) {
    // Many zeros: pieces of value 0 must be skipped.
    let text = String(pick(1, 9));
    for (let i = 1; i < length; i++) text += rand() < 0.6 ? '0' : String(pick(0, 9));
    num = Number(text);
  } else {
    num = pick(10 ** (length - 1), 10 ** length - 1);
  }
  const k = pick(1, String(num).length);
  return [num, k];
}
